<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import{ElMessage,ElMessageBox}from'element-plus';import CrudToolbar from '../../components/CrudToolbar.vue';import CrudTable from '../../components/crud/CrudTable.vue';import CrudForm from '../../components/crud/CrudForm.vue';import{fetchDictionaries,createDictionary,addDictionaryItem,updateDictionary,updateDictionaryItem,deleteDictionaryItem,toggleDictionary,toggleDictionaryItem}from'../../api/dictionary';
const dicts=ref<any[]>([]),code=ref(''),loading=ref(false),typeDialog=ref(false),itemDialog=ref(false),editingType=ref<any>(null),editingItem=ref<any>(null);const typeModel=ref<any>({dictCode:'',dictName:''}),itemModel=ref<any>({itemValue:'',itemLabel:'',sortOrder:0});const selected=computed(()=>dicts.value.find(d=>d.dictCode===code.value));const itemFields=[{code:'itemValue',label:'字典值',type:'text',table:true},{code:'itemLabel',label:'显示标签',type:'text',table:true},{code:'sortOrder',label:'排序',type:'number',table:true},{code:'enabled',label:'状态',type:'switch',table:true}];const typeForm=[{code:'dictCode',label:'字典编码',type:'text',required:true,editable:true},{code:'dictName',label:'字典名称',type:'text',required:true,editable:true}];const itemForm=[{code:'itemValue',label:'字典值',type:'text',required:true,editable:true},{code:'itemLabel',label:'显示标签',type:'text',required:true,editable:true},{code:'sortOrder',label:'排序',type:'number',editable:true}];async function load(){loading.value=true;try{dicts.value=(await fetchDictionaries()).data.data}catch(e:any){ElMessage.error(e.message||'字典加载失败')}finally{loading.value=false}}function openType(d?:any){editingType.value=d||null;typeModel.value=d?{dictCode:d.dictCode,dictName:d.dictName}:{dictCode:'',dictName:''};typeDialog.value=true}function openItem(i?:any){editingItem.value=i||null;itemModel.value=i?{itemValue:i.itemValue,itemLabel:i.itemLabel,sortOrder:i.sortOrder}:{itemValue:'',itemLabel:'',sortOrder:0};itemDialog.value=true}async function saveType(){try{editingType.value?await updateDictionary(editingType.value.dictCode,typeModel.value):await createDictionary(typeModel.value);typeDialog.value=false;await load();ElMessage.success('保存成功')}catch(e:any){ElMessage.error(e.message||'保存失败')}}async function saveItem(){try{editingItem.value?await updateDictionaryItem(editingItem.value.id,itemModel.value):await addDictionaryItem(code.value,itemModel.value);itemDialog.value=false;await load();ElMessage.success('保存成功')}catch(e:any){ElMessage.error(e.message||'保存失败')}}async function removeItem(i:any){try{await ElMessageBox.confirm(`确定删除字典项“${i.itemLabel}”吗？`,'删除确认',{type:'warning'});await deleteDictionaryItem(i.id);await load();ElMessage.success('删除成功')}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'删除失败')}}async function toggleTypeState(d:any){try{await toggleDictionary(d.dictCode,!d.enabled);await load()}catch(e:any){ElMessage.error(e.message||'操作失败')}}async function toggleItemState(i:any){try{await toggleDictionaryItem(i.id,!i.enabled);await load()}catch(e:any){ElMessage.error(e.message||'操作失败')}}onMounted(load);
</script>
<template><el-card><template #header><CrudToolbar title="字典管理"><el-button v-permission="'system:user:write'" type="primary" @click="openType()">新建字典</el-button></CrudToolbar></template><div class="crud-query"><el-select v-model="code" clearable placeholder="选择字典" style="width:280px"><el-option v-for="d in dicts" :key="d.dictCode" :label="`${d.dictName}（${d.dictCode}）`" :value="d.dictCode"/></el-select><el-button v-if="selected" v-permission="'system:user:write'" @click="openType(selected)">编辑字典</el-button><el-button v-if="selected" v-permission="'system:user:write'" @click="toggleTypeState(selected)">{{selected.enabled?'停用':'启用'}}</el-button><el-button v-permission="'system:user:write'" type="primary" plain :disabled="!code" @click="openItem()">新增字典项</el-button></div><CrudTable :fields="itemFields" :rows="selected?.items||[]" :loading="loading" :can-write="true"><template #actions="{row}"><el-button v-permission="'system:user:write'" link @click="openItem(row)">编辑</el-button><el-button v-permission="'system:user:write'" link @click="toggleItemState(row)">{{row.enabled?'停用':'启用'}}</el-button><el-button v-permission="'system:user:write'" link type="danger" @click="removeItem(row)">删除</el-button></template></CrudTable></el-card><CrudForm v-model="typeDialog" :title="editingType?'编辑字典':'新建字典'" :fields="typeForm" :model="typeModel" @update:model="typeModel=$event" @submit="saveType"/><CrudForm v-model="itemDialog" :title="editingItem?'编辑字典项':'新增字典项'" :fields="itemForm" :model="itemModel" @update:model="itemModel=$event" @submit="saveItem"/></template>
